def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    opp_def = sum(1 for a in opp if a == 'D')
    if n < 6:
        if last_opp == 'D':
            return 'D'
        return 'C'
    recent10 = opp[-10:]
    recent_opp_def = sum(1 for a in recent10 if a == 'D')
    recent5 = opp[-5:]
    r5_def = sum(1 for a in recent5 if a == 'D')
    if recent_opp_def >= 8:
        return 'D'
    if opp_def == 0:
        if n >= 94:
            return 'D'
        if n >= 12 and n % 7 == 0:
            return 'D'
        return 'C'
    if opp_def * 4 <= n:
        if n >= 95:
            return 'D'
        if last_opp == 'D' and last_me == 'C':
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        if recent_opp_def >= 1 and last_opp == 'D':
            return 'D'
        return 'C'
    if opp_def * 2 >= n:
        if r5_def >= 3:
            return 'D'
        if last_opp == 'D':
            return 'D' if rng.random() < 0.7 else 'C'
        if last_opp == 'C' and last_me == 'D':
            return 'D' if rng.random() < 0.4 else 'C'
        return 'D' if rng.random() < 0.3 else 'C'
    if last_opp == 'D':
        if last_me == 'C':
            if r5_def >= 2:
                return 'D'
            if n >= 20 and opp[-2] == 'C' and opp[-3] == 'C':
                return 'D'
            return 'D' if rng.random() < 0.75 else 'C'
        else:
            if r5_def >= 3:
                return 'D'
            if n >= 20 and opp[-2] == 'C' and opp[-3] == 'C':
                return 'C'
            return 'D' if rng.random() < 0.55 else 'C'
    else:
        if n >= 96:
            return 'D'
        if last_me == 'D':
            if r5_def == 0:
                return 'C'
            return 'D' if rng.random() < 0.35 else 'C'
        if recent_opp_def >= 3 and r5_def <= 1:
            return 'D'
        return 'C'
